cases.bad:
observer.observe(document.body, { childList: true, subtree: true });
// callback fire khi <video> mount (phase 1, src='')
// append foreign overlay ngay → Angular tiếp tục render trong cùng Zone.js task → wipe foreign elements
// setTimeout(0) defer cũng FAIL — Zone.js wrap setTimeout, callback vẫn trong Angular zone

cases.good:
function isVideoReady(v: HTMLVideoElement): boolean {
  return (v.src !== '' && v.src.startsWith('blob:')) || v.readyState >= 2;
}
// gate: chỉ init khi video có source thực (framework render done)
observer.observe(document.body, {
  childList: true, subtree: true,
  attributes: true, attributeFilter: ['src'], // catch phase-2 src change
});
// childList catch phase-1 (src='') → isVideoReady=false → skip
// attributes:['src'] catch phase-2 (src=blob:) → isVideoReady=true → init safe

// readyState >= 2 (HAVE_CURRENT_DATA) = direct source đã load enough data
// blob: URL = SPA streaming (HLS.js, mux.js) render done
// cả 2 signal = video có source thực, append safe
function isVideoReady(v: HTMLVideoElement): boolean {
  return (v.src !== '' && v.src.startsWith('blob:')) || v.readyState >= 2;
}
